/* ★ SUM(CASE WHEN EXISTS(...)) 는 **네 번째** 같은 에러다(2026-10-19).
     'Cannot perform an aggregate function on an expression containing an
      aggregate or a subquery'. 집계 안에 서브쿼리를 넣지 않는다.
     EXISTS 는 **LEFT JOIN 으로 바꾼다.** (앞선 세 번: 160/172/busStops) */
SELECT 샘플 = COUNT(*),
       현재에있음 = SUM(CASE WHEN t.bizes_id IS NOT NULL THEN 1 ELSE 0 END)
  FROM #s s
  LEFT JOIN silver.semas_store t
    ON t.is_current = 1 AND t.bizes_id = s.bizes_id;
PRINT '';
PRINT '--- 현재 스냅샷의 id 생김새 (형식이 같은지) ---';
SELECT TOP 3 bizes_id, bizes_nm FROM silver.semas_store WHERE is_current = 1;
DROP TABLE #s;
